// GLSL ES 3.x：顶点着色器中的 MVP
uniform mat4 uModel;
uniform mat4 uView;
uniform mat4 uProjection;

in vec3 aPosition;

void main() {
  vec4 modelPos = uModel * vec4(aPosition, 1.0);
  vec4 viewPos = uView * modelPos;
  vec4 clipPos = uProjection * viewPos;
  gl_Position = clipPos;
  // NDC = clipPos.xyz / clipPos.w 由 GPU 自动完成
}

// 由轮廓生成旋转曲面：参数 -> 顶点 + 索引
function lathe(profile, radialSeg, profileSeg) {
  const ring = sampleProfile(profile, profileSeg); // [[r, y], ...]
  const M = ring.length, N = radialSeg;
  const positions = [], indices = [];

  for (let i = 0; i < M; i++) {
    const [r, y] = ring[i];
    for (let j = 0; j < N; j++) {
      const theta = (j / N) * Math.PI * 2;
      positions.push(r * Math.cos(theta), y, r * Math.sin(theta));
    }
  }
  for (let i = 0; i < M - 1; i++) {
    for (let j = 0; j < N; j++) {
      const a = i * N + j, b = i * N + (j + 1) % N;
      const c = (i + 1) * N + j, d = (i + 1) * N + (j + 1) % N;
      indices.push(a, c, b, b, c, d);
    }
  }
  return { positions, indices };
}

